// js/auth.js

document.addEventListener('DOMContentLoaded', function() {
    const loginForm = document.getElementById('login-form');
    const cadastroForm = document.getElementById('cadastro-form');
    if (!loginForm && !cadastroForm) return;

    const showCadastroLink = document.getElementById('show-cadastro');
    const showLoginLink = document.getElementById('show-login');
    const showAlert = (message) => alert(message);

    if (showCadastroLink && showLoginLink && loginForm && cadastroForm) {
        showCadastroLink.addEventListener('click', (e) => { e.preventDefault(); loginForm.style.display = 'none'; cadastroForm.style.display = 'block'; });
        showLoginLink.addEventListener('click', (e) => { e.preventDefault(); cadastroForm.style.display = 'none'; loginForm.style.display = 'block'; });
    }

    if (loginForm) {
        loginForm.addEventListener('submit', async (e) => {
            e.preventDefault();
            try {
                const res = await fetch('../php/login.php', { method: 'POST', body: new FormData(loginForm) });
                const json = await res.json();
                if (res.ok) {
                    // refresh nav then go to index
                    await fetch('../php/verificar_sessao.php', { cache: 'no-store' });
                    window.location.href = 'index.html';
                } else {
                    showAlert(json.mensagem);
                }
            } catch (err) {
                showAlert('Erro de comunicação com o servidor.');
            }
        });
    }

    if (cadastroForm) {
        cadastroForm.addEventListener('submit', async (e) => {
            e.preventDefault();
            const senha = cadastroForm.querySelector('input[name="senha"]').value;
            const confirma = cadastroForm.querySelector('input[name="confirma_senha"]').value;
            if (senha !== confirma) { showAlert('As senhas não coincidem!'); return; }
            try {
                const res = await fetch('../php/cadastro.php', { method: 'POST', body: new FormData(cadastroForm) });
                const json = await res.json();
                showAlert(json.mensagem);
                if (res.ok) { cadastroForm.reset(); if (showLoginLink) showLoginLink.click(); }
            } catch (err) {
                showAlert('Erro de comunicação com o servidor.');
            }
        });
    }
});

// js/auth.js

document.addEventListener('DOMContentLoaded', function() {
    const loginForm = document.getElementById('login-form');
    const cadastroForm = document.getElementById('cadastro-form');
    const showCadastroLink = document.getElementById('show-cadastro');
    const showLoginLink = document.getElementById('show-login');

    // Alternância entre formulários
    if (showCadastroLink) {
        showCadastroLink.addEventListener('click', function(e) {
            e.preventDefault();
            loginForm.style.display = 'none';
            cadastroForm.style.display = 'block';
        });
    }

    if (showLoginLink) {
        showLoginLink.addEventListener('click', function(e) {
            e.preventDefault();
            cadastroForm.style.display = 'none';
            loginForm.style.display = 'block';
        });
    }

    // Login
    if (loginForm) {
        loginForm.addEventListener('submit', async function(e) {
            e.preventDefault();

            const formData = new FormData(loginForm);

            try {
                const response = await fetch('../php/login.php', {
                    method: 'POST',
                    body: formData
                });

                const result = await response.json();

                if (response.ok) {
                    alert(result.mensagem);
                    window.location.href = 'index.html';
                } else {
                    alert(result.mensagem || 'Erro no login');
                }
            } catch (error) {
                console.error('Erro no login:', error);
                alert('Erro de comunicação. Tente novamente.');
            }
        });
    }

    // Cadastro
    if (cadastroForm) {
        cadastroForm.addEventListener('submit', async function(e) {
            e.preventDefault();

            const formData = new FormData(cadastroForm);
            const senha = formData.get('senha');
            const confirmaSenha = formData.get('confirma_senha');

            if (senha !== confirmaSenha) {
                alert('As senhas não coincidem!');
                return;
            }

            try {
                const response = await fetch('../php/cadastro.php', {
                    method: 'POST',
                    body: formData
                });

                const result = await response.json();

                if (response.ok) {
                    alert(result.mensagem);
                    // Voltar para o formulário de login
                    cadastroForm.style.display = 'none';
                    loginForm.style.display = 'block';
                    cadastroForm.reset();
                } else {
                    alert(result.mensagem || 'Erro no cadastro');
                }
            } catch (error) {
                console.error('Erro no cadastro:', error);
                alert('Erro de comunicação. Tente novamente.');
            }
        });
    }
});

// js/main.js

document.addEventListener('DOMContentLoaded', function() {
    async function atualizarNavegacao() {
        try {
            const res = await fetch('../php/verificar_sessao.php', { cache: 'no-store' });
            const session = await res.json();
            const nav = document.querySelector('header nav');
            if (!nav) return;

            let links = `
                <a href="index.html">Início</a>
            `;

            // Exibir 'Agendar' apenas se for cliente
            if (session.logado && session.role === 'cliente') {
                links += `<a href="agendamento.html">Agendar</a>`;
            }

            if (session.logado) {
                // Mostrar 'Meus Agendamentos' apenas para cliente
                if (session.role === 'cliente') {
                    links += `<a href="meus-agendamentos.html">Meus Agendamentos</a>`;
                }
                if (session.role === 'admin') {
                    links += `<a href="admin-agendamentos.html">Painel Admin</a>`;
                }
                links += `<a href="#" id="logout-link">Sair</a>`;
            } else {
                links += `
                    <a href="auth.html">Login</a>
                    <a href="auth.html">Cadastrar</a>
                `;
            }
            nav.innerHTML = links;
        } catch (e) {
            console.error('Erro ao verificar sessão:', e);
        }
    }

    async function handleLogoutClick(event) {
        const target = event.target;
        if (!target || target.id !== 'logout-link') return;
        event.preventDefault();
        try {
            const res = await fetch('../php/logout.php', { method: 'POST' });
            if (res.ok) {
                await atualizarNavegacao();
                window.location.href = 'index.html';
            } else {
                alert('Erro ao tentar sair');
            }
        } catch (e) {
            console.error('Erro no logout:', e);
            alert('Erro de comunicação ao tentar sair.');
        }
    }

    // Inicializa
    atualizarNavegacao();
    document.body.addEventListener('click', handleLogoutClick);
});

